{"files": "[
  {
    "path": "characters.json",
    "content": "{\n  \"main_characters\": [\n    {\n      \"name\": \"沈寂\",\n      \"role\": \"protagonist\",\n      \"identity\": \"无限流资深玩家，ID: Silent_Abyss，通关记录排名前十，被称为"读档狂魔"\",\n      \"traits\": [\"冷静克制\", \"偏执守护\", \"自我欺骗\", \"孤独成瘾\", \"恐惧遗忘\"],\n      \"overt_motivation\": \"带"新人"通关所有副本，让她成为合格的玩家\",\n      \"covert_motivation\": \"不想再失去任何人——三年前他失去了唯一的队友\",\n      \"secret_fear\": \"如果她消失了，他将彻底坠入虚无\",\n      \"misperception_of_other\": \"以为温眠是系统生成的"新手引导NPC"，因为她的行为模式太过"剧本化"\",\n      \"hidden_connection\": \"三年前曾在第一个副本中遇到过真正的温眠，她死在他面前，他读档无数次都救不回她\"\n    },\n    {\n      \"name\": \"温眠\",\n      \"role\": \"deuteragonist\",\n      \"identity\": \"三年前的新人玩家，第一个副本死亡后成为"已注销玩家"，现在是沈寂执念生成的幻觉\",\n      \"traits\": [\"天真好奇\", \"直觉敏锐\", \"温暖治愈\", \"模糊的自我\", \"恐惧被抛弃\"],\n      \"overt_motivation\": \"跟着沈寂通关，成为真正的玩家\",\n      \"covert_motivation\": \"想知道自己是谁——她隐约感觉自己"不完整"\",\n      \"secret_fear\": \"如果沈寂不再看着她，她是否还存在\",\n      \"misperception_of_other\": \"以为沈寂是系统派来的"高级NPC引导员"，因为他太强了，强到不像真人\",\n      \"hidden_connection\": \"她是沈寂三年执念的产物，身体保留着三年前的战斗记忆，但意识是"新生成"的\"\n    }\n  ],\n  \"supporting_characters\": [\n    {\n      \"name\": \"系统提示音\",\n      \"function\": \"反转点\",\n      \"identity\": \"主神空间的系统AI\",\n      \"description\": \"冰冷的机械音，负责播报副本规则和玩家状态。在第八个副本中播报了揭示真相的关键信息。\"\n    }\n  ],\n  \"relationship_dynamics\": \"复活点绑定者——一人死亡，另一人读档。这本是无限流中最亲密的羁绊，却在"她是幻觉"的真相下变得残酷：他每次读档，都是在用自己的执念重新"创造"她。三层认知差构成Meta核心：沈寂从"以为她是NPC"到"发现她是幻觉"再到"选择继续欺骗自己"；温眠始终以为沈寂是NPC，不知道自己是幻觉；读者从第一章就知道设定，但要到第八章才和沈寂一起发现真相。\"\n}"
  },
